```ts
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import { attachControl, setCameraLimits } from "@babylonjs/lite";

function normalizeDistanceRange(minDistance: number, maxDistance: number): { lower: number; upper: number } {
  let lower = Math.min(minDistance, maxDistance);
  let upper = Math.max(minDistance, maxDistance);

  if (Number.isNaN(lower)) lower = 0;
  if (Number.isNaN(upper)) upper = Infinity;

  if (lower === -Infinity) lower = 0;
  if (upper === -Infinity) upper = Infinity;
  if (lower === Infinity && upper === Infinity) {
    lower = 0;
    upper = Infinity;
  }

  if (lower > upper) {
    const tmp = lower;
    lower = upper;
    upper = tmp;
  }

  if (lower < 0) lower = 0;
  if (upper < lower) upper = lower;

  return { lower, upper };
}

export function attachLimitedOrbit(...): () => void {
  const { lower, upper } = normalizeDistanceRange(minDistance, maxDistance);

  const previousLowerRadiusLimit = camera.lowerRadiusLimit;
  const previousUpperRadiusLimit = camera.upperRadiusLimit;

  const clampRadiusNow = () => {
    const radius = camera.radius;
    let clamped = false;

    if (!Number.isFinite(radius)) {
      if (radius === Infinity) {
        camera.radius = Number.isFinite(upper) ? upper : Number.isFinite(lower) ? lower : 0;
      } else if (radius === -Infinity) {
        camera.radius = Number.isFinite(lower) ? lower : 0;
      } else {
        camera.radius = Number.isFinite(lower) && lower > 0 ? lower : 0;
      }
      clamped = true;
    } else if (radius < lower) {
      camera.radius = lower;
      clamped = true;
    } else if (radius > upper) {
      camera.radius = upper;
      clamped = true;
    }

    if (clamped) {
      camera.inertialRadiusOffset = 0;
    }

    camera._clampToLimits?.();
  };

  camera.lowerRadiusLimit = lower;
  camera.upperRadiusLimit = upper;
  clampRadiusNow();

  const detachLimits = setCameraLimits(camera, { lowerRadiusLimit: lower, upperRadiusLimit: upper }, scene);
  const detachControls = attachControl(camera, canvas, scene, { keyboard: false });

  clampRadiusNow();

  let disposed = false;
  return () => {
    if (disposed) return;
    disposed = true;

    try {
      detachControls();
    } finally {
      try {
        detachLimits();
      } finally {
        camera.lowerRadiusLimit = previousLowerRadiusLimit;
        camera.upperRadiusLimit = previousUpperRadiusLimit;
      }
    }
  };
}
```

